def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = [v for v in Counter(v for row in grid for v in row) if v != bg]

    for color in colors:
        runs = []
        for c in range(w):
            r = 0
            while r < h:
                if grid[r][c] == color:
                    start = r
                    while r < h and grid[r][c] == color:
                        r += 1
                    end = r - 1
                    if end - start + 1 >= 3:
                        runs.append((c, start, end))
                else:
                    r += 1

        for i, (c1, top1, bot1) in enumerate(runs):
            for c2, top2, bot2 in runs[i + 1:]:
                if c2 > c1 + 1 and top1 == top2 and bot1 == bot2:
                    out = [row[:] for row in grid]
                    for r in range(top1 + 1, bot1):
                        for c in range(c1 + 1, c2):
                            out[r][c] = 4
                    return out

    return [row[:] for row in grid]
